{"cards": [{"node_code": "N_a5d160e2c26f4693", "definition": "位于河流干流或支流沿岸，受河流水文、泥沙及地形条件制约的港口工程类型，涵盖河港选址、航道整治、码头结构及防淤措施。", "boundary": "本节点聚焦于“河流”环境下的港口工程特征。边界在于区分“河港”与“海港”（波浪与潮汐影响不同）、“河口港”（受潮汐与河流双重影响，水动力更复杂）。若内容涉及内河航运组织或船舶设计，不归入本节点。强调河流特有的泥沙淤积、水位变幅对工程的影响。", "includes": ["河港选址原则与河流地形适应性设计", "河港航道疏浚、护岸及防淤工程措施", "适应河流水位变幅的码头结构与系泊设施"], "excludes": ["海港、湖港或河口港特有的波浪与潮汐工程问题", "内河船舶设计与制造", "河流生态治理（非港口工程目的）"], "sibling_distinctions": [{"other_code": "N_1534a9fa589f2c47", "rule": "河港主要受河流径流影响，波浪作用弱；海港受海洋波浪与潮汐影响显著，防波堤设计差异大。"}, {"other_code": "N_380aac752ef9022b", "rule": "河港位于河流上游或中游，水动力以单向流为主；河口港位于河流入海口，受潮汐往复流与波浪共同作用，泥沙运动更复杂。"}, {"other_code": "N_b8b5613758683914", "rule": "河港位于流动水体，需考虑水流冲刷与泥沙输移；湖港位于静水或缓流水体，主要考虑风浪与湖底地质。"}], "cross_boundary_rule": "若内容涉及“河海过渡区”港口，需根据主导水动力特征判断：若以潮汐和波浪为主，归入河口港或海港；若以河流径流为主，归入河港。"}, {"node_code": "N_380aac752ef9022b", "definition": "位于河流入海口或河口区域，同时受河流径流与海洋潮汐、波浪双重影响的港口工程类型，涵盖河口航道治理、防波与防淤设计。", "boundary": "本节点聚焦于“河口”这一特殊过渡水域的港口工程。边界在于区分“河港”（纯河流环境）与“海港”（纯海洋环境）。河口港工程需解决泥沙淤积、潮汐往复流、波浪与河流动力叠加等复杂问题。若内容仅涉及河口生态或水文研究，不归入本节点。", "includes": ["河口港选址与潮汐、波浪、河流动力耦合分析", "河口航道整治、导堤及防淤工程措施", "适应河口复杂水动力环境的码头与防波设施设计"], "excludes": ["纯河流上游河港工程", "纯外海海港工程", "河口生态环境治理（非港口工程目的）"], "sibling_distinctions": [{"other_code": "N_a5d160e2c26f4693", "rule": "河口港受潮汐往复流和波浪影响，水动力双向且复杂；河港主要受单向河流径流影响，波浪作用较弱。"}, {"other_code": "N_1534a9fa589f2c47", "rule": "河口港位于河海过渡区，需兼顾河流泥沙与海洋波浪；海港位于外海，主要应对海洋波浪与潮汐，无河流径流直接干扰。"}], "cross_boundary_rule": "若港口位于河口但主要功能服务于内河航运且工程措施以河流整治为主，可关联河港；若主要服务于远洋或沿海航运且工程措施以防波和潮汐适应为主，主挂载河口港。"}, {"node_code": "N_b8b5613758683914", "definition": "位于湖泊、水库等静水或缓流水体沿岸的港口工程类型，涵盖湖港选址、风浪防护、码头结构及湖底地质适应性设计。", "boundary": "本节点聚焦于“湖泊/水库”环境下的港口工程特征。边界在于区分“湖港”与“河港”（水流速度与泥沙输移不同）、“海港”（波浪与潮汐影响不同）。湖港工程主要考虑风浪、湖底地质、水位季节性变化及生态敏感性。若内容涉及湖泊治理或水利枢纽，不归入本节点。", "includes": ["湖港选址与湖泊地形、地质适应性设计", "湖港风浪防护、护岸及码头结构工程", "适应湖泊水位季节性变化的系泊与装卸设施"], "excludes": ["海港、河港或河口港特有的潮汐与河流动力工程问题", "水利枢纽工程（如大坝、船闸，除非作为湖港组成部分）", "湖泊生态治理（非港口工程目的）"], "sibling_distinctions": [{"other_code": "N_a5d160e2c26f4693", "rule": "湖港位于静水或缓流水体，主要考虑风浪与湖底地质；河港位于流动水体，需考虑水流冲刷与泥沙输移。"}, {"other_code": "N_1534a9fa589f2c47", "rule": "湖港无潮汐影响，波浪主要由风引起；海港受潮汐与海洋波浪影响，防波堤设计需应对更大波高与周期。"}], "cross_boundary_rule": "若港口位于水库且主要服务于水利枢纽调度，需根据工程主体判断：若以航运功能为主，归入湖港；若以水利设施为主，归入相关水利节点（若树中存在）。"}]}
